WITH lines AS (SELECT id, created_at, coupon_codes, attr_key, attr_value FROM carts LATERAL VIEW OUTER EXPLODE(attributes) x AS attr_key, attr_value) SELECT id, created_at, coupon_codes, attr_key, attr_value, CASE WHEN attr_key RLIKE '^(weight_kg|device)$' THEN 'GROUP_A' WHEN attr_key RLIKE '^(utm_source|gift)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS attr_key_zone FROM lines ORDER BY attr_key_zone DESC NULLS FIRST
